import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const dbPath = process.env.DB_PATH || './data/workboard.sqlite';
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec('CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskJSON = task => ({ ...task, completed: Boolean(task.completed) });
const page = readFileSync(new URL('./public/index.html', import.meta.url));
const script = readFileSync(new URL('./public/app.js', import.meta.url));
const style = readFileSync(new URL('./public/style.css', import.meta.url));

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskMatch) {
      const [, projectId, taskId] = taskMatch;
      if (!getProject.get(projectId)) return send(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) return send(res, 200, listTasks.all(projectId).map(taskJSON));
      if ((req.method === 'POST' && !taskId) || (req.method === 'PATCH' && taskId)) {
        let body = '';
        for await (const chunk of req) {
          body += chunk;
          if (body.length > 65536) return send(res, 413, { error: 'Request too large' });
        }
        let input;
        try { input = JSON.parse(body); } catch { return send(res, 400, { error: 'Invalid JSON' }); }
        if (req.method === 'POST') {
          const title = typeof input?.title === 'string' ? input.title.trim() : '';
          if (!title) return send(res, 400, { error: 'Task title is required' });
          const result = insertTask.run(projectId, title);
          return send(res, 201, taskJSON(getTask.get(projectId, result.lastInsertRowid)));
        }
        if (!getTask.get(projectId, taskId)) return send(res, 404, { error: 'Task not found' });
        if (typeof input?.completed !== 'boolean') return send(res, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return send(res, 200, taskJSON(getTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'GET') {
      if (path === '/health') return send(res, 200, { status: 'ok' });
      if (path === '/api/projects') return send(res, 200, listProjects.all());
      const apiMatch = path.match(/^\/api\/projects\/(\d+)$/);
      if (apiMatch) {
        const project = getProject.get(apiMatch[1]);
        return project ? send(res, 200, project) : send(res, 404, { error: 'Project not found' });
      }
      if (path === '/' || /^\/projects\/\d+$/.test(path)) return send(res, 200, page, 'text/html; charset=utf-8');
      if (path === '/app.js') return send(res, 200, script, 'text/javascript; charset=utf-8');
      if (path === '/style.css') return send(res, 200, style, 'text/css; charset=utf-8');
    }
    if (req.method === 'POST' && path === '/api/projects') {
      let body = '';
      for await (const chunk of req) {
        body += chunk;
        if (body.length > 65536) return send(res, 413, { error: 'Request too large' });
      }
      let input;
      try { input = JSON.parse(body); } catch { return send(res, 400, { error: 'Invalid JSON' }); }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return send(res, 201, getProject.get(result.lastInsertRowid));
    }
    send(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    send(res, 500, { error: 'Something went wrong' });
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p', '', { role: 'alert', class: 'error' });
    app.append(alert);
  }
  alert.textContent = message;
}

async function renderTasks(projectId) {
  const path = `/api/projects/${projectId}/tasks`;
  const form = element('form');
  const input = element('input', undefined, { id: 'task-title', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create task', { type: 'submit' });
  form.append(element('label', 'Task title', { for: 'task-title' }), input, create);
  const controls = element('div', undefined, { class: 'task-controls' });
  const filter = element('select', undefined, { id: 'task-filter' });
  for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value }));
  controls.append(element('label', 'Task filter', { for: 'task-filter' }), filter);
  const list = element('section', undefined, { 'aria-label': 'Tasks', class: 'project-list' });
  app.append(form, controls, list);
  let tasks = [];

  function drawTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = element('div', undefined, { 'data-testid': 'task-row', class: 'project-row' });
      const checkbox = element('input', undefined, { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
      checkbox.checked = task.completed;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        app.querySelector('[role="alert"]')?.remove();
        try {
          const updated = await request(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked })
          });
          Object.assign(task, updated);
          drawTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally { checkbox.disabled = false; }
      });
      row.append(element('span', task.title), checkbox);
      list.append(row);
    }
  }
  filter.addEventListener('change', drawTasks);
  create.disabled = true;
  try { tasks = await request(path); drawTasks(); }
  catch (error) { showError(error.message); }
  finally { create.disabled = false; }
  form.addEventListener('submit', async event => {
    event.preventDefault();
    app.querySelector('[role="alert"]')?.remove();
    const title = input.value.trim();
    if (!title) { showError('Task title is required'); return; }
    create.disabled = true;
    try {
      tasks.push(await request(path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
      }));
      drawTasks();
      input.value = '';
      input.focus();
    } catch (error) { showError(error.message); }
    finally { create.disabled = false; }
  });
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    const back = element('button', 'Projects', { type: 'button', class: 'secondary' });
    back.addEventListener('click', () => { location.href = '/'; });
    app.append(back);
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.append(element('h1', project.name));
      document.title = `${project.name} · Workboard`;
      await renderTasks(project.id);
    } catch (error) { showError(error.message); }
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create project', { type: 'submit' });
  form.append(label, input, create);
  const list = element('section', undefined, { 'aria-label': 'Projects', class: 'project-list' });
  app.append(form, list);

  function addProject(project) {
    const row = element('div', undefined, { 'data-testid': 'project-row', class: 'project-row' });
    const open = element('button', 'Open project', { type: 'button', class: 'secondary' });
    open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    row.append(element('span', project.name), open);
    list.append(row);
  }

  create.disabled = true;
  try {
    (await request('/api/projects')).forEach(addProject);
  } catch (error) { showError(error.message); }
  create.disabled = false;

  form.addEventListener('submit', async event => {
    event.preventDefault();
    app.querySelector('[role="alert"]')?.remove();
    const name = input.value.trim();
    if (!name) { showError('Project name is required'); return; }
    create.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
      });
      addProject(project);
      input.value = '';
      input.focus();
    } catch (error) { showError(error.message); }
    finally { create.disabled = false; }
  });
}

render();

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

test('launch, project validation, creation order, routes, and restart persistence', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = 18000 + Math.floor(Math.random() * 20000);
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(dir, 'projects.sqlite') },
      stdio: 'ignore'
    });
    for (let attempt = 0; attempt < 100; attempt++) {
      try { if ((await fetch(`${base}/health`)).ok) return; } catch {}
      await new Promise(resolve => setTimeout(resolve, 30));
    }
    throw new Error('Server did not become healthy');
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
  }
  try {
    await start();
    const health = await fetch(`${base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const blank = await create('   ');
    assert.equal(blank.status, 400);
    assert.deepEqual(await blank.json(), { error: 'Project name is required' });
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('Second project')).json();
    const expected = [first, second];
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`, '/app.js', '/style.css']) {
      assert.equal((await fetch(`${base}${path}`)).status, 200);
    }
    const taskPath = `/api/projects/${first.id}/tasks`;
    async function tasksFor(projectId) {
      return (await fetch(`${base}/api/projects/${projectId}/tasks`)).json();
    }
    async function createTask(title) {
      return fetch(`${base}${taskPath}`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
      });
    }
    async function complete(taskId, completed, projectId = first.id) {
      return fetch(`${base}/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed })
      });
    }
    assert.deepEqual(await tasksFor(first.id), []);
    const blankTask = await createTask('  ');
    assert.equal(blankTask.status, 400);
    assert.deepEqual(await blankTask.json(), { error: 'Task title is required' });
    assert.deepEqual(await tasksFor(first.id), []);
    const taskResponse = await createTask('  First task  ');
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const nextTask = await (await createTask('Second task')).json();
    assert.deepEqual(await tasksFor(first.id), [task, nextTask]);
    assert.deepEqual(await tasksFor(second.id), []);
    assert.equal((await complete(task.id, true, second.id)).status, 404);
    assert.equal((await complete(task.id, 'true')).status, 400);
    task.completed = true;
    assert.deepEqual(await (await complete(task.id, true)).json(), task);
    task.completed = false;
    assert.deepEqual(await (await complete(task.id, false)).json(), task);
    task.completed = true;
    await complete(task.id, true);
    await stop();
    await start();
    assert.deepEqual(await tasksFor(first.id), [task, nextTask]);
    assert.deepEqual(await tasksFor(second.id), []);
    assert.equal((await fetch(`${base}/projects/${first.id}`)).status, 200);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
  } finally {
    await stop();
    await rm(dir, { recursive: true, force: true });
  }
});

